//! Cross-language conformance tests: every value in spec/ledger-vectors.json
//! (generated by an independent Python implementation) must be reproduced.

use ledger_core::{
    canonical, entry_hash, payload_hash, sha256_hex, verify_chain, Bill, ChainItem, FailureCode,
    LedgerEntry, Signer, GENESIS_HASH,
};
use serde_json::Value;

fn vectors() -> Value {
    let raw = include_str!("../../../spec/ledger-vectors.json");
    serde_json::from_str(raw).expect("vectors parse")
}

fn chain_items(v: &Value) -> Vec<ChainItem> {
    v["chain"]
        .as_array()
        .unwrap()
        .iter()
        .map(|c| ChainItem {
            bill: serde_json::from_value(c["bill"].clone()).unwrap(),
            entry: serde_json::from_value(c["entry"].clone()).unwrap(),
            entry_hash: c["entryHash"].as_str().unwrap().to_string(),
            signature: Some(c["signature"].as_str().unwrap().to_string()),
        })
        .collect()
}

#[test]
fn canonical_cases_match_reference() {
    let v = vectors();
    for case in v["canonicalCases"].as_array().unwrap() {
        let got = canonical(&case["input"]).unwrap();
        assert_eq!(
            got,
            case["canonical"].as_str().unwrap(),
            "case {}",
            case["name"]
        );
        assert_eq!(sha256_hex(&got), case["sha256"].as_str().unwrap());
    }
}

#[test]
fn floats_are_rejected() {
    let v = vectors();
    for bad in v["rejectFloats"].as_array().unwrap() {
        assert!(canonical(bad).is_err(), "should reject {bad}");
    }
}

#[test]
fn bill_and_entry_hashes_match_reference() {
    let v = vectors();
    for c in v["chain"].as_array().unwrap() {
        let bill: Bill = serde_json::from_value(c["bill"].clone()).unwrap();
        let entry: LedgerEntry = serde_json::from_value(c["entry"].clone()).unwrap();
        assert_eq!(
            bill.canonical().unwrap(),
            c["billCanonical"].as_str().unwrap()
        );
        assert_eq!(payload_hash(&bill).unwrap(), entry.payload_hash);
        assert_eq!(
            entry.canonical().unwrap(),
            c["entryCanonical"].as_str().unwrap()
        );
        assert_eq!(
            entry_hash(&entry).unwrap(),
            c["entryHash"].as_str().unwrap()
        );
    }
}

#[test]
fn signer_reproduces_reference_signatures_and_public_key() {
    let v = vectors();
    let signer = Signer::from_secret(v["testSecret"].as_str().unwrap()).unwrap();
    assert_eq!(
        signer.public_key_base64(),
        v["publicKeyBase64"].as_str().unwrap()
    );
    for c in v["chain"].as_array().unwrap() {
        let sig = signer
            .sign_entry_hash(c["entryHash"].as_str().unwrap())
            .unwrap();
        assert_eq!(sig, c["signature"].as_str().unwrap());
    }
}

#[test]
fn reference_chain_verifies() {
    let v = vectors();
    let items = chain_items(&v);
    let report = verify_chain(
        v["shopId"].as_str().unwrap(),
        &items,
        Some(v["publicKeyBase64"].as_str().unwrap()),
    );
    assert!(report.valid, "{report:?}");
    assert_eq!(report.checked, 3);
    assert_eq!(items[0].entry.prev_hash, GENESIS_HASH);
}

#[test]
fn edited_bill_is_detected() {
    let v = vectors();
    let mut items = chain_items(&v);
    items[1].bill.total_paise += 100;
    let report = verify_chain("shop_demo_01", &items, None);
    assert_eq!(report.failure.unwrap().code, FailureCode::PayloadMismatch);
}

#[test]
fn deleted_bill_is_detected() {
    let v = vectors();
    let mut items = chain_items(&v);
    items.remove(1);
    let f = verify_chain("shop_demo_01", &items, None).failure.unwrap();
    assert_eq!(f.code, FailureCode::SeqGap);
    assert_eq!(f.seq, 2);
}

#[test]
fn reordered_chain_is_detected() {
    let v = vectors();
    let mut items = chain_items(&v);
    items.swap(1, 2);
    let f = verify_chain("shop_demo_01", &items, None).failure.unwrap();
    assert_eq!(f.code, FailureCode::SeqGap);
}

#[test]
fn rewritten_entry_with_recomputed_hash_fails_signature() {
    // An attacker edits a bill AND recomputes every hash, but cannot re-sign.
    let v = vectors();
    let mut items = chain_items(&v);
    let last = items.len() - 1;
    items[last].bill.payment_mode = ledger_core::PaymentMode::Cash;
    items[last].entry.payload_hash = payload_hash(&items[last].bill).unwrap();
    items[last].entry_hash = entry_hash(&items[last].entry).unwrap();
    let pk = v["publicKeyBase64"].as_str().unwrap();
    let f = verify_chain("shop_demo_01", &items, Some(pk))
        .failure
        .unwrap();
    assert_eq!(f.code, FailureCode::BadSignature);
}

#[test]
fn entry_from_other_shop_is_detected() {
    let v = vectors();
    let items = chain_items(&v);
    let f = verify_chain("someone_else", &items, None).failure.unwrap();
    assert_eq!(f.code, FailureCode::ShopMismatch);
}
